<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthorizedChalleges;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\PublicLogin;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\User\Application\Usecase\ConsentUsecase;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

class ConsentForm implements OidcStep
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly PublicLogin $publicLogin,
        private readonly ConsentUsecase $publicConsent,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer
    ) {
    }

    private function paint(?AuthenticationResult $pe, string $locale, string $base, string $tenant, AuthorizedChalleges $challenges, ?array $body, ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $locale = '';

        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign")
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("consent.title");
        $error = $pe?->errorMessage
            ? $translator->get("consent.error-format", [$error = $translator->get('error.' . strtolower($pe?->errorMessage))])
            : false;

        $help = $translator->get("consent.help");
        $code = $translator->get("consent.code");
        $send = $translator->get("consent.send");

        $backLabel = $translator->get("consent.back-label");
        $backText = $translator->get(
            "consent.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $backLabel . "\" />"]
        );
        $pending = html_entity_decode($this->publicConsent->getPendingConsent($tenant, $challenges->username));

        $error = $error ? '<p class="error">' . $error . '</p>' : '';

        $step = StepInput::STEP_CONSENT;
        $response->getBody()->write(
            $this->decorator->getFullPage(
                $request,
                'Consent',
                $js . <<< HTML
                    <h1>{$title}</h1>
                    <p>{$help}</p>
                    {$error}
                    <form method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <label>{$code}
                            <textarea type="text" name="conditions" id="conditions" readonly>
                                {$pending}
                            </textarea>
                        </label>
                        <label>Acept: 
                            <input type="checkbox" name="accept" value="accept" />
                        </label>
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                    HTML,
                $locale
            )
        );
        return $response;
    }

    public function autenticate(
        AuthenticationRequest $request,
        string $tenant,
        string $issuer,
        string $csid,
        string $state,
        string $nonce,
        AuthorizedChalleges $challenges,
        mixed $body
    ): PublicLoginAuthResponse {
        $accept = isset($body['accept']);
        if ($accept) {
            $this->publicConsent->storeAcceptedConsent($tenant, $challenges->username);
            return $this->publicLogin->preAutenticate($request, $challenges, $tenant, $issuer, $csid, $state, $nonce);
        } else {
            throw new LoginException(auth: AuthenticationResult::consentRequired(), message: 'must_accept_condition');
        }
    }

    public function run(
        StepInput $input,
        ResponseInterface $response,
        ?AuthenticationResult $error,
        ?string $step,
        ?string $csid
    ): StepResult {
        $legacyChallenges = $input->challenges->toLegacy();
        $base = rtrim($input->context->baseUrl, '/') . '/oauth';

        if ($csid !== null) {
            $auth = $this->autenticate(
                $input->authRequest,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce,
                $legacyChallenges,
                $input->body ?? []
            );
            return StepResult::proceed($auth);
        }

        $response = $this->paint(
            $error,
            $input->context->locale,
            $base,
            $input->context->tenant,
            $legacyChallenges,
            $input->body ?? [],
            $input->request,
            $response
        );

        return StepResult::render($response);
    }

}
